import {SCHEMA} from '/Users/lingxiaotian/Programs/personal/PromptHub/packages/db/src/schema.ts';
import {PromptDB, FolderDB} from '/Users/lingxiaotian/Programs/personal/PromptHub/packages/db/src/index.ts';
