const root='/private/tmp/prompthub-whitebox-yXvztv';
const body='Synthetic audit content\n'.repeat(64);
const samples=[];
let active=null;
const restores=[];
for(const owner of [fs,fsp]) {
  for(const name of ['readFileSync','writeFileSync','cpSync','renameSync','readFile','writeFile']) {
    if(typeof owner[name]!=='function') continue;
    const original=owner[name];
    owner[name]=function(...args) {
      if(active && typeof args[0]==='string' && args[0].startsWith(root+'/')) active.fs[name]=(active.fs[name]??0)+1;
      return original.apply(this,args);
    };
    restores.push(()=>owner[name]=original);
  }
}
function instrument(database) {
  const original=database.prepare;
  database.prepare=function(sql) {
    if(active) {
      active.prepares++;
      if(/FROM prompt_versions WHERE prompt_id/i.test(sql.replace(/\s+/g,' '))) active.versionQueries++;
      if(/(?:INSERT|UPDATE|DELETE)/i.test(sql)) active.writePrepares++;
    }
    return original.call(this,sql);
  };
}
async function measure(label,metadata,operation) {
  active={label,...metadata,prepares:0,versionQueries:0,writePrepares:0,fs:{}};
  const entry=active;
  const timerStart=performance.now();
  let timerDelay;
  const timer=new Promise(resolve=>setTimeout(()=>{timerDelay=performance.now()-timerStart;resolve();},0));
  const started=performance.now();
  await operation();
  entry.operationMs=performance.now()-started;
  active=null;
  await timer;
  entry.timerDelayMs=timerDelay;
  samples.push(entry);
  console.log(JSON.stringify(entry));
}
function seed(directory,count) {
  fs.mkdirSync(path.join(directory,'data'),{recursive:true});
  const database=new Database(path.join(directory,'data','prompthub.db'));
  database.exec(SCHEMA);
  const prompts=new PromptDB(database);
  const ids=[];
  database.transaction(()=>{
    for(let i=0;i<count;i++) {
      const prompt=prompts.create({title:`Synthetic ${i}`,userPrompt:body});
      prompts.update(prompt.id,{userPrompt:body+i});
      ids.push(prompt.id);
    }
  })();
  return {database,ids};
}
try {
  for(const count of [32,128,256]) {
    const directory=path.join(root,'core-'+count);
    configureRuntimePaths({userDataPath:directory});
    writeRuntimeLayoutState(directory);
    const {database,ids}=seed(directory,count);
    try {
      writeCanonicalStorageAuthority(directory,{consistencyId:'d'.repeat(64),operationId:'whitebox-audit'});
      publishCanonicalPromptGraph(database);
      instrument(database);
      const prompts=new CanonicalPromptDB(database);
      await measure('canonical-single-update',{count},()=>prompts.update(ids[0],{title:'Changed synthetic title'}));
      if(count===128) await measure('canonical-eight-single-updates',{count,batchSize:8},()=>{for(const id of ids.slice(0,8))prompts.update(id,{isFavorite:true});});
    } finally {database.close();resetRuntimePaths();}
  }
  const directory=path.join(root,'rules');
  configureRuntimePaths({userDataPath:directory});
  writeRuntimeLayoutState(directory);
  const {database}=seed(directory,128);
  writeCanonicalStorageAuthority(directory,{consistencyId:'e'.repeat(64),operationId:'whitebox-rules'});
  publishCanonicalPromptGraph(database);
  database.close();
  const current=initDatabase();
  instrument(current);
  let initCalls=0;
  const service=createRulesWorkspaceService({getRulesDir,assertStorageAvailable(){},createRuleDb:()=>{initCalls++;return new RuleDB(initDatabase());},getPlatformGlobalRulePath:platform=>path.join(directory,'targets',String(platform)),getPlatformRootDir:platform=>path.join(directory,'targets',platform.id)});
  await measure('rules-first-cached-list',{count:128},async()=>{const result=await service.listCachedRuleDescriptors();samples.push({label:'rules-first-list-result',descriptors:result.length,initCalls});});
  initCalls=0;
  await measure('rules-second-cached-list',{count:128},async()=>{await service.listCachedRuleDescriptors();});
  samples.push({label:'rules-second-list-init-calls',initCalls});
  closeDatabase();resetRuntimePaths();
  process.env.DATA_ROOT=path.join(root,'web');
  process.env.JWT_SECRET='synthetic-audit-key-'.repeat(3);
  const {syncPromptWorkspaceFromDatabase}=await import('/Users/lingxiaotian/Programs/personal/PromptHub/apps/web/src/services/prompt-workspace.ts');
  const seeded=seed(process.env.DATA_ROOT,128);
  try {
    instrument(seeded.database);
    await measure('web-full-workspace-export',{count:128},()=>syncPromptWorkspaceFromDatabase(seeded.database,new PromptDB(seeded.database),new FolderDB(seeded.database)));
  } finally {seeded.database.close();}
} finally {
  active=null;
  for(const restore of restores.reverse())restore();
  closeDatabase();resetRuntimePaths();
  fs.writeFileSync(path.join(root,'measurements.json'),JSON.stringify({pid:process.pid,endedAt:new Date().toISOString(),samples},null,2)+'\n');
}

import fs from "node:fs";
import path from "node:path";
import { performance } from "node:perf_hooks";
import Database from "/Users/lingxiaotian/Programs/personal/PromptHub/packages/db/src/adapter.ts";
import { SCHEMA } from "/Users/lingxiaotian/Programs/personal/PromptHub/packages/db/src/schema.ts";
import { CanonicalSkillDB } from "/Users/lingxiaotian/Programs/personal/PromptHub/packages/core/src/canonical-skill-db.ts";
import { configureRuntimePaths, resetRuntimePaths, writeRuntimeLayoutState } from "/Users/lingxiaotian/Programs/personal/PromptHub/packages/core/src/runtime-paths.ts";
import { writeCanonicalStorageAuthority } from "/Users/lingxiaotian/Programs/personal/PromptHub/packages/core/src/canonical-storage-authority.ts";
const root = "/private/tmp/prompthub-whitebox-yXvztv/skill";
const samples: Array<Record<string, unknown>> = [];
let active: Record<string, number> | null = null;
const restorers: Array<() => void> = [];
for (const name of ["readFileSync", "writeFileSync", "copyFileSync", "renameSync"] as const) {
  const original = fs[name];
  // Probe interop only: forwarding the overloaded fs functions preserves all arguments.
  const forward = original as (...args: unknown[]) => unknown;
  fs[name] = ((...args: unknown[]) => {
    if (active && typeof args[0] === "string" && args[0].startsWith(root + "/")) active[name] = (active[name] ?? 0) + 1;
    return forward(...args);
  }) as typeof original;
  restorers.push(() => { fs[name] = original; });
}
try {
  for (const packageFileCount of [32, 128]) {
    const directory = path.join(root, String(packageFileCount));
    const source = path.join(directory, "source");
    fs.mkdirSync(source, { recursive: true });
    fs.writeFileSync(path.join(source, "SKILL.md"), "---\nname: synthetic-skill\ndescription: Audit fixture\n---\n# Skill\n");
    for (let index = 1; index < packageFileCount; index++) fs.writeFileSync(path.join(source, `fixture-${index}.txt`), "Synthetic package asset\n".repeat(128));
    fs.mkdirSync(path.join(directory, "data"));
    configureRuntimePaths({ userDataPath: directory });
    writeRuntimeLayoutState(directory);
    writeCanonicalStorageAuthority(directory, { consistencyId: "f".repeat(64), operationId: "whitebox-skill" });
    const database = new Database(path.join(directory, "data", "prompthub.db"));
    try {
      database.exec(SCHEMA);
      const skills = new CanonicalSkillDB(database);
      const skill = skills.create({ name: "synthetic-skill", protocol_type: "skill", content: "# Skill\n", local_repo_path: source, is_favorite: false });
      active = {};
      const entry = active;
      const started = performance.now();
      const updated = skills.update(skill.id, { is_favorite: true });
      active = null;
      if (!updated?.is_favorite) throw new Error("Synthetic Skill update did not persist");
      samples.push({ label: "skill-favorite-only-update", packageFileCount, fs: entry, operationMs: performance.now() - started });
    } finally { database.close(); resetRuntimePaths(); }
  }
} finally {
  active = null;
  for (const restore of restorers.reverse()) restore();
  resetRuntimePaths();
  fs.writeFileSync("/private/tmp/prompthub-whitebox-yXvztv/skill-measurements.json", JSON.stringify({ pid: process.pid, samples }, null, 2));
}

