it("records marketplace fanout while the library tab is active", async () => {
  let finishRemote: (() => void) | undefined;
  const remoteGate = new Promise<void>((resolve) => { finishRemote = resolve; });
  const sources = ["source-a", "source-b", "source-c"].map((id) => ({
    id, displayName: id, repository: "https://example.invalid/repository",
    marketplaceFile: "marketplace.json", trustLevel: "official" as const,
  }));
  const listMarket = vi.fn(async () => { await remoteGate; return []; });
  window.api.plugin.listMarketSources = vi.fn(async () => sources);
  window.api.plugin.listMarket = listMarket;
  window.api.plugin.getLibrary = vi.fn(async () => ({ kind: "prompthub-plugin-library" as const, version: 1 as const, updatedAt: "2026-10-10T00:00:00.000Z", plugins: [] }));
  usePluginStore.setState({ selectedTab: "library", marketEntries: [], customStoreSources: [], hasLoadedTargetInventory: false });
  const pending = usePluginStore.getState().load();
  await vi.waitFor(() => expect(listMarket).toHaveBeenCalledTimes(sources.length));
  samples.push({ label: "plugin-library-tab-load", sourceCount: sources.length, marketCalls: listMarket.mock.calls.length, localLibraryAvailableBeforeRemote: usePluginStore.getState().library !== null, loadingUntilRemoteFinishes: usePluginStore.getState().isLoading });
  finishRemote?.();
  await pending;
  expect(usePluginStore.getState().isLoading).toBe(false);
});

