    replaceSettings, replaceSources: vi.fn(async () => true), replaceRecoveryPaths: vi.fn(async () => true),
    getOrCreateDeviceId: vi.fn(async () => "synthetic"), isIndexedDbMigrationDone: vi.fn(async () => true), markIndexedDbMigrationDone: vi.fn(async () => true),
