  samples.push({ label: "settings-single-action", mainSettingCalls: setMain.mock.calls.length, canonicalSnapshotCalls: replaceSettings.mock.calls.length, legacySettingsWrites: storage.mock.calls.filter(([key]) => key === "prompthub-settings").length });
  expect(setMain).toHaveBeenCalledOnce(); expect(replaceSettings).toHaveBeenCalledOnce();
  replaceSettings.mockClear(); storage.mockClear();
  for (const opacity of [0.12, 0.24, 0.36, 0.48, 0.60]) {
    useSettingsStore.getState().setBackgroundImageOpacity(opacity);
