  storage.mockRestore();
});

it("measures the reachable line-diff implementation", () => {
  for (const lineCount of [500, 1000, 2000]) {
    const oldText = Array.from({ length: lineCount }, (_, index) => `Original ${index}`).join("\n");
    const newText = Array.from({ length: lineCount }, (_, index) => `Changed ${index}`).join("\n");
    const started = performance.now();
    const diff = generateTextDiff(oldText, newText);
    samples.push({ label: "renderer-line-diff", lineCount, dpCells: (lineCount + 1) ** 2, resultRows: diff.length, operationMs: performance.now() - started });
    expect(diff).toHaveLength(lineCount * 2);
  }
});

